var s=`1019-pho-ga`;var n=`world-1019`;var a=`VN`;var t=`southeast-asia`;var r=4;var o=93;var g={en:`Pho Ga`,ua:`Фо га`};var h={en:`Pho Ga is a dish from Vietnam prepared with chicken carcass, chicken thigh, yellow onion, fish sauce. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Фо га, страва кухні країни В'єтнам, яку готують із таких продуктів: курячий каркас, куряче стегно, жовта цибуля, рибний соус. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 80 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 80 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:80,i:[[`chicken-carcass`,850,`g`],[`chicken-thigh`,650,`g`],[`water`,2200,`ml`],[`ground-ginger`,65,`g`],[`yellow-onion`,200,`g`],[`star-anise`,2,`pcs`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`fish-sauce`,45,`ml`],[`white-granulated-sugar`,12,`g`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`rice-noodles`,420,`g`],[`water`,1100,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`bean-sprouts`,200,`g`],[`cilantro`,25,`g`],[`thai-basil`,25,`g`],[`green-onion`,40,`g`],[`lime`,2,`pcs`]]}];var m={slug:s,id:n,country:`VN`,region:t,servings:4,minutes:93,title:g,text:h,steps:l};export{a as country,m as default,n as id,o as minutes,t as region,r as servings,s as slug,l as steps,h as text,g as title};